mapper.update:
UPDATE sys_notice_read
SET notice_id = #{noticeId},
    user_id = #{userId},
    read_time = #{readTime}
WHERE read_id = #{readId}

mapper.select:
SELECT u.user_id AS userId, u.login_name AS loginName, u.user_name AS userName, d.dept_name AS deptName, u.phonenumber AS phonenumber, r.read_time AS readTime FROM sys_notice_read r INNER JOIN sys_user u ON u.user_id = r.user_id AND u.del_flag = '0' LEFT JOIN sys_dept d ON d.dept_id = u.dept_id WHERE r.notice_id = #{noticeId}
AND (u.login_name LIKE concat('%', #{searchValue}, '%') OR u.user_name LIKE concat('%', #{searchValue}, '%'))
ORDER BY r.read_time DESC
